"use client";

import { useAppStore } from "../store/useAppStore";
import { PyramidLogo } from "../components/ui/PyramidLogo";
import { useRouter } from "next/navigation";
import { useEffect } from "react";

export default function Home() {
  const { isAuthenticated, loginAsGuest } = useAppStore();
  const router = useRouter();

  // If already authenticated, push them to the tasks dashboard
  useEffect(() => {
    if (isAuthenticated) {
      router.push("/dashboard");
    }
  }, [isAuthenticated, router]);

  const handleGuestLogin = () => {
    // 1. Update your global Zustand state
    loginAsGuest();

    // 2. Save the session to the browser so the "Create Task" logic can read it!
    localStorage.setItem(
      "ableSpace_user",
      JSON.stringify({
        name: "Guest User",
        role: "guest",
        avatar: "https://github.com/shadcn.png",
      }),
    );

    // 3. Redirect to the dashboard
    router.push("/dashboard");
  };

  return (
    <div className="flex min-h-screen flex-col items-center justify-center bg-white p-4">
      {/* Logo */}
      <div className="mb-6 flex items-center gap-2">
        <div className="flex h-8 w-8 items-center justify-center rounded-xl bg-[#111111] text-white">
          <PyramidLogo />
        </div>
        <span className="text-xl font-bold text-black">Pyramid</span>
      </div>

      {/* Login Card */}
      <div className="w-full max-w-md rounded-3xl border border-gray-200 bg-white p-8 shadow-sm">
        <div className="mb-8 text-center">
          <h1 className="mb-2 text-2xl font-bold text-black">
            Let&apos;s get back on track
          </h1>
          <p className="text-sm text-gray-500">
            Enter your email below to login to your account.
          </p>
        </div>

        <div className="flex flex-col gap-3">
          <button
            onClick={handleGuestLogin}
            className="w-full rounded-full bg-black py-3 text-sm font-medium text-white transition-opacity hover:bg-gray-800"
          >
            Continue as Guest
          </button>

          <button className="flex w-full items-center justify-center gap-2 rounded-full border border-gray-300 bg-white py-3 text-sm font-medium text-black transition-colors hover:bg-gray-50">
            <svg className="h-5 w-5" viewBox="0 0 24 24">
              <path
                d="M22.56 12.25c0-.78-.07-1.53-.2-2.25H12v4.26h5.92c-.26 1.37-1.04 2.53-2.21 3.31v2.77h3.57c2.08-1.92 3.28-4.74 3.28-8.09z"
                fill="#4285F4"
              />
              <path
                d="M12 23c2.97 0 5.46-.98 7.28-2.66l-3.57-2.77c-.98.66-2.23 1.06-3.71 1.06-2.86 0-5.29-1.93-6.16-4.53H2.18v2.84C3.99 20.53 7.7 23 12 23z"
                fill="#34A853"
              />
              <path
                d="M5.84 14.09c-.22-.66-.35-1.36-.35-2.09s.13-1.43.35-2.09V7.07H2.18C1.43 8.55 1 10.22 1 12s.43 3.45 1.18 4.93l2.85-2.22.81-.62z"
                fill="#FBBC05"
              />
              <path
                d="M12 5.38c1.62 0 3.06.56 4.21 1.64l3.15-3.15C17.45 2.09 14.97 1 12 1 7.7 1 3.99 3.47 2.18 7.07l3.66 2.84c.87-2.6 3.3-4.53 6.16-4.53z"
                fill="#EA4335"
              />
            </svg>
            Login with Google
          </button>
        </div>
      </div>

      <p className="mt-8 max-w-xs text-center text-xs text-gray-400">
        By clicking continue, you agree to our{" "}
        <a href="#" className="underline">
          Terms of Service
        </a>{" "}
        and{" "}
        <a href="#" className="underline">
          Privacy Policy
        </a>
      </p>
    </div>
  );
}
